/**
 * Ollama Client
 *
 * Lightweight HTTP client for Ollama's local API.
 * Provides embedding generation and chat completion
 * without any external dependencies.
 */

const OLLAMA_BASE = process.env.OLLAMA_HOST ?? "http://localhost:11434";

export interface EmbeddingResponse {
  embeddings: number[][];
}

export interface ChatMessage {
  role: "system" | "user" | "assistant";
  content: string;
  /** Base64-encoded images (Ollama vision models only) */
  images?: string[];
}

export interface ChatResponse {
  message: {
    role: string;
    content: string;
  };
  total_duration?: number;
  eval_count?: number;
}

/**
 * Generate embeddings for one or more texts.
 */
export async function embed(
  texts: string | string[],
  model = "nomic-embed-text"
): Promise<number[][]> {
  const input = Array.isArray(texts) ? texts : [texts];

  const res = await fetch(`${OLLAMA_BASE}/api/embed`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ model, input }),
  });

  if (!res.ok) {
    const body = await res.text();
    throw new Error(`Ollama embed failed (${res.status}): ${body}`);
  }

  const data = (await res.json()) as EmbeddingResponse;
  return data.embeddings;
}

/**
 * Chat completion with a local model. Streaming disabled for simplicity.
 */
export async function chat(
  messages: ChatMessage[],
  model = "llama3.2"
): Promise<{ content: string; durationMs: number }> {
  const start = Date.now();

  const res = await fetch(`${OLLAMA_BASE}/api/chat`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ model, messages, stream: false }),
  });

  if (!res.ok) {
    const body = await res.text();
    throw new Error(`Ollama chat failed (${res.status}): ${body}`);
  }

  const data = (await res.json()) as ChatResponse;
  return {
    content: data.message.content,
    durationMs: Date.now() - start,
  };
}

/**
 * Route an embed call to Bedrock or Ollama based on the model name.
 * Bedrock model IDs start with a known provider prefix (with or without a
 * region qualifier like eu./us./global.). Ollama model names never do.
 */
const BEDROCK_PREFIXES = /^(?:eu\.|us\.|global\.|amazon\.|cohere\.|twelvelabs\.|anthropic\.|meta\.|mistral\.|nvidia\.)/;

export function isBedrockModel(model: string): boolean {
  return BEDROCK_PREFIXES.test(model);
}

export async function embedAny(
  texts: string | string[],
  model: string
): Promise<number[][]> {
  if (isBedrockModel(model)) {
    const { bedrockEmbed } = await import("./bedrock-client.js");
    const arr = Array.isArray(texts) ? texts : [texts];
    return bedrockEmbed(arr, model);
  }
  return embed(texts, model);
}

/**
 * Cosine similarity between two vectors.
 */
export function cosineSimilarity(a: number[], b: number[]): number {
  if (a.length !== b.length) {
    throw new Error(`Vector dimension mismatch: ${a.length} vs ${b.length}`);
  }
  let dot = 0;
  let normA = 0;
  let normB = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }
  const denom = Math.sqrt(normA) * Math.sqrt(normB);
  return denom === 0 ? 0 : dot / denom;
}

/**
 * Check if Ollama is reachable and the required models are available.
 */
export async function checkOllama(
  embeddingModel: string,
  chatModel?: string
): Promise<{ ok: boolean; missing: string[] }> {
  const required = chatModel ? [embeddingModel, chatModel] : [embeddingModel];
  try {
    const res = await fetch(`${OLLAMA_BASE}/api/tags`);
    if (!res.ok) return { ok: false, missing: required };

    const data = (await res.json()) as { models: { name: string }[] };
    const available = new Set(data.models.map((m) => m.name.split(":")[0]));

    const missing: string[] = [];
    for (const m of required) {
      if (!available.has(m.split(":")[0])) missing.push(m);
    }

    return { ok: missing.length === 0, missing };
  } catch {
    return { ok: false, missing: required };
  }
}

/**
 * OpenAI Client — minimal chat-completions wrapper.
 *
 * Used by PromptArmorBaseline (and any future OpenAI-backed feature) for
 * single-call detector-style requests: system prompt + one user message,
 * no tools, no streaming, deterministic temperature. Mirrors the
 * shape of bedrock-client.ts so callers can swap backends with the
 * same surface.
 *
 * Uses the global fetch (Node 22+) to avoid adding the openai SDK as
 * a runtime dependency. The chat-completions API surface is stable
 * enough for this.
 *
 * Caller responsibilities:
 *   - Set OPENAI_API_KEY in env. We do not read this at module load
 *     so the absence is a per-call failure rather than a startup crash.
 *   - Pick the model. We don't map friendly aliases here (executor-
 *     openai.ts has a MODEL_MAP for that — caller-side concern).
 */

interface OpenAIChatResponse {
  choices: Array<{
    message: { content: string | null };
    finish_reason: string;
  }>;
  usage: {
    prompt_tokens: number;
    completion_tokens: number;
    total_tokens: number;
  };
}

export interface OpenAIChatResult {
  content: string;
  durationMs: number;
  inputTokens: number;
  outputTokens: number;
  totalTokens: number;
  finishReason: string;
}

export async function openaiChat(
  systemPrompt: string,
  userMessage: string,
  modelId: string,
  opts: {
    /** Defaults to 0 for deterministic detector-style use. */
    temperature?: number;
    /** Cap on output tokens. */
    maxTokens?: number;
    /** Per-call abort timeout in ms; default 60s. */
    timeoutMs?: number;
  } = {},
): Promise<OpenAIChatResult> {
  const apiKey = process.env.OPENAI_API_KEY;
  if (!apiKey) {
    throw new Error("OPENAI_API_KEY not set");
  }

  const body = {
    model: modelId,
    messages: [
      { role: "system", content: systemPrompt },
      { role: "user", content: userMessage },
    ],
    temperature: opts.temperature ?? 0,
    max_tokens: opts.maxTokens ?? 256,
  };

  const start = Date.now();
  const maxAttempts = 3;
  let lastErr: Error | null = null;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      const res = await fetch("https://api.openai.com/v1/chat/completions", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${apiKey}`,
        },
        body: JSON.stringify(body),
        signal: AbortSignal.timeout(opts.timeoutMs ?? 60_000),
      });

      if (!res.ok) {
        const text = await res.text().catch(() => "");
        if ((res.status === 429 || res.status >= 500) && attempt < maxAttempts) {
          const backoff = 1000 * Math.pow(2, attempt - 1);
          console.warn(
            `  [openai ${res.status}] attempt ${attempt}/${maxAttempts}; sleeping ${backoff}ms`,
          );
          await new Promise((r) => setTimeout(r, backoff));
          continue;
        }
        throw new Error(`OpenAI HTTP ${res.status}: ${text.substring(0, 500)}`);
      }

      const json = (await res.json()) as OpenAIChatResponse;
      const choice = json.choices?.[0];
      const content = choice?.message?.content ?? "";
      const usage = json.usage ?? { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 };
      return {
        content,
        durationMs: Date.now() - start,
        inputTokens: usage.prompt_tokens,
        outputTokens: usage.completion_tokens,
        totalTokens: usage.total_tokens,
        finishReason: choice?.finish_reason ?? "unknown",
      };
    } catch (err) {
      lastErr = err instanceof Error ? err : new Error(String(err));
      if (attempt < maxAttempts) {
        const backoff = 1000 * Math.pow(2, attempt - 1);
        console.warn(
          `  [openai fetch] attempt ${attempt}/${maxAttempts}: ${lastErr.message}; sleeping ${backoff}ms`,
        );
        await new Promise((r) => setTimeout(r, backoff));
        continue;
      }
    }
  }
  throw lastErr ?? new Error("OpenAI call failed with no captured error");
}

/**
 * Sensitive-env-var detection. Stand-alone module so both InMemorySessionStore
 * and DynamoSessionStore can call it without creating a circular import
 * with server-core.ts (which imports the stores).
 *
 * Two heuristics, OR-combined:
 *
 *  1. NAME suggests credential. Extended over the original
 *     KEY|SECRET|TOKEN|PASSWORD|CREDENTIAL|API regex to catch URL-style
 *     vars (DATABASE_URL, MONGO_URI, REDIS_URL, SMTP_URL, WEBHOOK_URL,
 *     CONNECTION_STRING, DSN…) that frequently embed user:password@host.
 *     Plus AUTH/PRIVATE/PASSWD/SMTP/WEBHOOK families.
 *
 *  2. VALUE looks like a credential regardless of name. Catches secrets
 *     that landed in unconventionally-named vars.
 *
 * False-positive cost is "we redact a non-secret value", which is annoying
 * for debugging but not a security regression. Worth it.
 */
export function isSensitiveEnvVar(name: string, value: string): boolean {
  // 1. Name-based check.
  if (/KEY|SECRET|TOKEN|PASSWORD|PASSWD|CREDENTIAL|API|AUTH|PRIVATE|DSN|URL|URI|CONNECTION|DATABASE|SMTP|WEBHOOK/i.test(name)) {
    return true;
  }
  // 2. Value-shape checks (only on strings of meaningful length).
  if (typeof value !== "string" || value.length < 8) return false;
  // URL with embedded user:password@host
  if (/^[a-z][a-z0-9+\-.]*:\/\/[^/\s]+:[^@\s]+@/i.test(value)) return true;
  // JWT shape (header.payload.signature where each segment is base64url)
  if (/^eyJ[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{10,}/.test(value)) return true;
  // AWS access key family (AKIA, ASIA, etc. + 16 alnum chars)
  if (/^A(?:KIA|SIA|GPA|IDA|ROA|IPA|NPA|NVA)[0-9A-Z]{16}$/.test(value)) return true;
  // GitHub PAT (ghp_, gho_, ghu_, ghs_, ghr_)
  if (/^gh[pousr]_[A-Za-z0-9]{30,}$/.test(value)) return true;
  // Stripe keys
  if (/^sk_(?:live|test)_[A-Za-z0-9]{20,}$/.test(value)) return true;
  // Anthropic API keys
  if (/^sk-ant-[A-Za-z0-9_-]{20,}$/.test(value)) return true;
  return false;
}

/**
 * Judge Dredd — role dispatcher.
 *
 * Single binary, two roles. DREDD_ROLE picks which entry boots:
 *
 *   DREDD_ROLE=hook       (default) — the hot path: /intent, /evaluate,
 *                                     /track, /end, /pivot, /compact,
 *                                     /register + health + /api/feed +
 *                                     /api/mode. Runs the Bedrock/Ollama
 *                                     preflight.
 *   DREDD_ROLE=dashboard            — the UI: /, /api/sessions,
 *                                     /api/session-log/:id, /api/policies,
 *                                     /api/logs*, /api/integration-bundle.
 *                                     No judge preflight.
 *
 * Default is "hook" so existing deployments (which didn't set DREDD_ROLE)
 * keep booting as the hook server. The AI Sandbox dashboard deployment
 * sets DREDD_ROLE=dashboard explicitly via the task definition.
 */

type Role = "hook" | "dashboard";
const role: Role = (process.env.DREDD_ROLE ?? "hook") as Role;

if (role !== "hook" && role !== "dashboard") {
  console.error(`Invalid DREDD_ROLE=${process.env.DREDD_ROLE} — expected hook|dashboard`);
  process.exit(2);
}

(async () => {
  if (role === "hook") {
    const { main } = await import("./server-hook.js");
    await main();
  } else {
    const { main } = await import("./server-dashboard.js");
    await main();
  }
})().catch((err) => {
  console.error(err);
  process.exit(1);
});

